<!doctype html>
<html lang="id"><head><meta charset="utf-8"><title>{{ $addendum->addendum_no }}</title><style>body{font:14px Arial,sans-serif;color:#111;line-height:1.55;margin:42px}.center{text-align:center}.meta{width:100%;border-collapse:collapse;margin:22px 0}.meta td{padding:7px;border:1px solid #bbb}.sign{display:grid;grid-template-columns:1fr 1fr;gap:80px;margin-top:70px;text-align:center}@media print{button{display:none}}</style></head>
<body><button onclick="window.print()">Cetak</button><div class="center"><h2>ADDENDUM KONTRAK PENAMBAHAN MUTU</h2><strong>{{ $addendum->addendum_no }}</strong></div>
<p>Addendum ini merupakan satu kesatuan dari Kontrak Penambahan Mutu <strong>{{ $addendum->contract->contract_no }}</strong>.</p>
<table class="meta"><tr><td>Perusahaan pelaksana</td><td>{{ $addendum->contract->company?->nama_cabang }}</td></tr><tr><td>Customer</td><td>{{ $addendum->contract->customer?->nama }}</td></tr><tr><td>Unit</td><td>{{ $addendum->contract->unit?->perumahan?->nama_perusahaan }} — {{ $addendum->contract->unit?->display_label }}</td></tr><tr><td>Tanggal addendum</td><td>{{ optional($addendum->addendum_date)->format('d/m/Y') }}</td></tr><tr><td>Alasan perubahan</td><td>{{ $addendum->reason }}</td></tr><tr><td>Tambahan nilai</td><td>Rp {{ number_format($addendum->value_change, 0, ',', '.') }}</td></tr><tr><td>Nilai kontrak setelah addendum</td><td>Rp {{ number_format($addendum->contract->contract_value, 0, ',', '.') }}</td></tr><tr><td>Perubahan tanggal selesai</td><td>{{ optional($addendum->finish_date_change)->format('d/m/Y') ?: '-' }}</td></tr></table>
<p>Ketentuan lain dalam kontrak induk yang tidak diubah oleh addendum ini tetap berlaku.</p><div class="sign"><div>Customer<br><br><br><br><strong>{{ $addendum->contract->customer?->nama }}</strong></div><div>{{ $addendum->contract->company?->nama_cabang }}<br><br><br><br><strong>Pejabat Berwenang</strong></div></div></body></html>
